// Map the Upwork actor's output onto a common shape.
// Apify returns [] for an empty/failed run; with alwaysOutputData the node
// upstream hands us a single {} item. Emit a sentinel instead of nothing --
// a Code node that returns [] stops its whole branch with no error.
const normalizeUrl = u => {
  if (!u) return u;
  try {
    const url = new URL(u);
    url.search = '';
    url.hash = '';
    let s = url.toString();
    if (s.endsWith('/')) s = s.slice(0, -1);
    return s;
  } catch (e) { return u; } // not a real URL (e.g. test fixtures) -- leave as-is
};
const rows = $input.all().map(i => i.json).filter(j => j && Object.keys(j).length);
const leads = rows.map(j => ({ json: {
  title: j.title || j.jobTitle || 'Untitled',
  description: j.description || j.snippet || '',
  url: normalizeUrl(j.url || j.link || ''),
  platform: 'Upwork',
}})).filter(x => x.json.url);
return leads.length ? leads : [{ json: { __empty: 'Upwork', __raw: rows.length } }];

// apify~website-content-crawler returns { url, text, markdown, metadata: {title, description} }.
// Title lives under metadata, not at the top level.
// Keep only individual job posts -- the crawler also saves the board/list pages it starts from.
const normalizeUrl = u => {
  if (!u) return u;
  try {
    const url = new URL(u);
    url.search = '';
    url.hash = '';
    let s = url.toString();
    if (s.endsWith('/')) s = s.slice(0, -1);
    return s;
  } catch (e) { return u; } // not a real URL (e.g. test fixtures) -- leave as-is
};
const JOB_URL = /^https:\/\/(problogger\.com\/jobs\/job\/|cozyjobs\.com\/jobs\/)/;
const rows = $input.all().map(i => i.json).filter(j => j && Object.keys(j).length);
const leads = rows.map(j => ({ json: {
  title: (j.metadata && j.metadata.title) || j.title || 'Untitled',
  description: j.text || j.markdown || '',
  url: normalizeUrl(j.url || (j.metadata && j.metadata.canonicalUrl) || ''),
  platform: 'Company Site',
}})).filter(x => JOB_URL.test(x.json.url));
return leads.length ? leads : [{ json: { __empty: 'Company Site', __raw: rows.length } }];

// Cheap filter BEFORE the OpenAI call, so scoring only runs on plausible leads.
// Wide on purpose -- the model does the real tiering. Edit as niches shift.
const KEYWORDS = [
  // Pillar 1: evidence-based nutrition & health
  'medical', 'clinical', 'nutrition', 'dietitian', 'dietetics', 'health',
  'healthcare', 'wellness', 'pharma', 'patient', 'peer-reviewed', 'evidence-based',
  // Pillar 2: tech, SaaS, B2B, AI
  'saas', 'b2b', 'technical writer', 'technology', 'software', 'api',
  'developer', 'fintech', 'cybersecurity', 'machine learning', 'ai ', 'artificial intelligence',
  // Core formats in either pillar
  'white paper', 'whitepaper', 'long-form', 'explainer', 'research writer',
  'thought leadership', 'case study', 'academic',
  // Secondary tier -- let it through, let the model score it 4-6
  'seo', 'blog', 'ghostwrit', 'copywriter', 'content writer', 'newsletter'
];

const all = $input.all().map(i => i.json);
const empties = all.filter(j => j.__empty);
const leads = all.filter(j => !j.__empty);

// ponytail: a FAILED/ABORTED Apify run also yields an empty dataset, so it
// surfaces here rather than at the status check. Split the IF per terminal
// status if you need to tell "broken actor" from "no results today".
if (leads.length === 0) {
  throw new Error(
    'Every source returned 0 items (' +
    empties.map(e => e.__empty).join(', ') +
    '). Check the Apify actor IDs, the actor input schema, and APIFY_TOKEN.'
  );
}

// Hard block: MSc in Nutrition, not an RD/RDN credential -- a posting that
// demands one is an auto-rejection, so drop it before the paid OpenAI call.
// \bRDN?\b is case-sensitive on purpose: lowercase "rd" is road/3rd/etc.
const NEEDS_RD = t => /\bRDN?\b/.test(t) || /registered dietitian|registered dietician/i.test(t);

return leads
  .filter(j => KEYWORDS.some(k => (j.title + ' ' + j.description).toLowerCase().replace(/problogger/g, '').includes(k)))
  .filter(j => !NEEDS_RD(j.title + ' ' + j.description))
  .map(json => ({ json }));

// The chat completion's message content is a JSON *string* -- parse it,
// then attach the original scraped fields so nothing is lost.
const source = $('Loop Leads').item.json;
const content = $input.first().json.choices[0].message.content;
let ai;
try {
  ai = JSON.parse(content);
} catch (e) {
  ai = {
    client_name: 'Unknown',
    need_summary: '',
    budget_signal: 'Not specified',
    skill_fit_score: 0,
    value_score: 0,
    confidence: 'Low',
    score_reasoning: 'AI response was not valid JSON -- check the prompt/model.',
    recommended_action: 'Consider',
    niche_tag: '',
    verified_facts: [],
    inferred_signals: [],
    unknown_factors: [],
    positive_signals: [],
    negative_signals: [],
    urgency: 'Low',
  };
}

// Long Text Airtable fields hold evidence lists as newline-joined bullets,
// not JSON -- mirrors lib/airtable.ts's toLines/fromLines on the app side.
const lines = v => (Array.isArray(v) ? v : []).filter(Boolean).join('\n');

return [{ json: {
  title: source.title,
  description: source.description,
  url: source.url,
  platform: source.platform,
  client_name: ai.client_name || 'Unknown',
  need_summary: ai.need_summary || '',
  budget_signal: ai.budget_signal || 'Not specified',
  skill_fit_score: ai.skill_fit_score || 0,
  value_score: ai.value_score || 0,
  confidence: ai.confidence || 'Low',
  score_reasoning: ai.score_reasoning || '',
  recommended_action: ai.recommended_action || 'Consider',
  niche_tag: ai.niche_tag || '',
  verified_facts: lines(ai.verified_facts),
  inferred_signals: lines(ai.inferred_signals),
  unknown_factors: lines(ai.unknown_factors),
  positive_signals: lines(ai.positive_signals),
  negative_signals: lines(ai.negative_signals),
  urgency: ai.urgency || 'Low',
}}];

const records = $input.first().json.records || [];
const rows = records.map(r => {
  const f = r.fields;
  return '<li><strong>' + f['Fit Score'] + '/10</strong> -- ' + f['Title'] + ' (' + f['Client/Company'] + ')<br/>' +
    '<a href="' + f['Source URL'] + '">View listing</a></li>';
}).join('');

return [{ json: {
  count: records.length,
  html: '<h2>' + records.length + ' strong lead(s) found today</h2><ul>' + rows + '</ul>'
}}];

// Trigger type was already determined once, in "Start Run" -- reuse it so
// there's a single source of truth per run instead of detecting it twice.
const sd = $getWorkflowStaticData('global');
return $input.all().map(i => ({ json: { ...i.json, scheduled: sd.trigger === 'scheduled' } }));

// Resets the per-run counters "Record Source Stats" and "Write Run Record"
// use below. Workflow static data, not a database -- fine for one on-demand
// button + one daily cron on a single n8n instance (same accepted trade-off
// as lib/run-status.ts on the website side). Two runs overlapping would
// clobber each other's counters; not a realistic risk for one freelancer's
// workflow.
let trigger = 'scheduled';
try { $('Manual Run (Webhook)').item; trigger = 'manual'; } catch (e) {}
const sd = $getWorkflowStaticData('global');
sd.runId = $execution.id;
sd.trigger = trigger;
sd.startedAt = $now.toISO();
sd.sources = {};
sd.itemsDiscovered = 0;
return $input.all();

// Per-source health, computed once before filtering/scoring so a source
// that quietly returns nothing is visible in the Runs record even when the
// overall run "succeeds" (only ALL sources being empty throws, in Keyword
// Pre-Filter below -- a single dead source among healthy ones does not).
const all = $input.all().map(i => i.json);
const sd = $getWorkflowStaticData('global');
sd.sources = sd.sources || {};
for (const j of all) {
  const src = j.__empty || j.platform;
  if (!src) continue;
  if (!(src in sd.sources)) sd.sources[src] = 0;
  if (!j.__empty) sd.sources[src] += 1;
}
sd.itemsDiscovered = all.filter(j => !j.__empty).length;
return $input.all();

// Builds this run's Airtable "Runs" record. $input.all() here is Loop
// Leads' accumulated "done" output -- every lead the loop touched, whether
// skipped as a duplicate or created. A created item is Airtable's create
// response ({id, fields}); a duplicate-skip item keeps its original
// {title, description, url, platform} shape (see "Is New Lead?" wiring) --
// that's how the two are told apart, no extra tagging needed.
const items = $input.all().map(i => i.json);
const sd = $getWorkflowStaticData('global');
const AI_FAILURE_MARKER = 'AI response was not valid JSON -- check the prompt/model.';

const created = items.filter(i => i.id && i.fields);
const duplicates = items.length - created.length;
const aiFailures = created.filter(i => i.fields['Score Reasoning'] === AI_FAILURE_MARKER).length;

const itemsDiscovered = sd.itemsDiscovered || 0;
const itemsFiltered = Math.max(itemsDiscovered - items.length, 0);

const sourceStatus = Object.entries(sd.sources || {})
  .map(([name, count]) => `${name}: ${count} item${count === 1 ? '' : 's'}`)
  .join(' | ') || 'No sources ran';

const startedAt = sd.startedAt || $now.toISO();
const durationSec = Math.round((new Date($now.toISO()).getTime() - new Date(startedAt).getTime()) / 1000);

return [{ json: {
  runId: sd.runId || $execution.id,
  trigger: sd.trigger === 'manual' ? 'Manual' : 'Scheduled',
  startedAt,
  endedAt: $now.toISO(),
  durationSec,
  overallStatus: itemsDiscovered === 0 ? 'No Items Found' : 'Success',
  sourceStatus,
  itemsDiscovered,
  itemsFiltered,
  newOpportunities: created.length,
  duplicates,
  aiAnalyses: created.length,
  aiFailures,
  errors: '',
}}];
